"""Builds code_runtime/source/smaa.inc: the SPIR-V of the SMAA passes and the lookup textures of SMAA.

The passes are tools/smaa/smaa.glsl, which includes SMAA.hlsl of https://github.com/iryoku/smaa (with the fix of its issue #11, the only change; MIT
license, see tools/smaa/LICENSE), compiled with glslangValidator (package glslang-tools). The lookup textures are
read from the AreaTex.h and SearchTex.h of that project, which are downloaded unless a folder with them is given.
The generated file is committed, so building the project needs neither.

Usage: generate_smaa.py <output.inc> [folder with AreaTex.h and SearchTex.h]
"""
import hashlib
import os
import re
import struct
import subprocess
import sys
import tempfile
import urllib.request

BASE = "https://raw.githubusercontent.com/iryoku/smaa/master/Textures/"
HASHES = {
    "AreaTex.h": "1933bf43ce86ba71f7ed5f0fa94b148610c634dc3395b9bc67a817d51ee73af2",
    "SearchTex.h": "1fac315ab5f87b60083c9b8387af17f056204d3d1bf21500f2acc5b3e8c1a37a",
}
HERE = os.path.dirname(os.path.abspath(__file__))
PASSES = ["EDGES", "WEIGHTS", "BLEND", "RESOLVE"]


def compile_shader(stage, define):
    with tempfile.TemporaryDirectory() as folder:
        out = os.path.join(folder, "out.spv")
        subprocess.check_call([
            "glslangValidator", "-V", "-S", stage, "-I" + os.path.join(HERE, "smaa"),
            "-DSTAGE_" + ("VERT" if stage == "vert" else "FRAG"), "-DPASS_" + define,
            os.path.join(HERE, "smaa", "smaa.glsl"), "-o", out], stdout=subprocess.DEVNULL)
        data = open(out, "rb").read()
    return list(struct.unpack("<%dI" % (len(data) // 4), data))


def texture_bytes(name, array, folder):
    if folder:
        raw = open(os.path.join(folder, name), "rb").read()
    else:
        raw = urllib.request.urlopen(BASE + name).read()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != HASHES[name]:
        sys.exit("%s is not the file this was written for (sha256 %s)." % (name, digest))
    text = raw.decode("latin-1")
    body = text[text.index(array):]
    body = body[body.index("{") + 1:body.index("}")]
    return bytes(int(v, 16) for v in re.findall(r"0x[0-9a-fA-F]{2}", body))


def emit_words(out, name, words):
    out.write("static const unsigned int %s[] = {\n" % name)
    for index in range(0, len(words), 8):
        out.write("\t" + ", ".join("0x%08x" % w for w in words[index:index + 8]) + ",\n")
    out.write("};\n")


def emit_bytes(out, name, data):
    out.write("static const unsigned char %s[] = {\n" % name)
    for index in range(0, len(data), 32):
        out.write("\t" + ",".join(str(b) for b in data[index:index + 32]) + ",\n")
    out.write("};\n")


folder = sys.argv[2] if len(sys.argv) > 2 else None
area = texture_bytes("AreaTex.h", "areaTexBytes", folder)
search = texture_bytes("SearchTex.h", "searchTexBytes", folder)
assert len(area) == 160 * 560 * 2 and len(search) == 64 * 16

with open(sys.argv[1], "w", newline="\n") as out:
    out.write("// Generated by tools/generate_smaa.py, do not edit. SMAA is Copyright (C) 2013 Jorge Jimenez, Jose I. Echevarria,\n")
    out.write("// Belen Masia, Fernando Navarro and Diego Gutierrez, MIT license (tools/smaa/LICENSE).\n")
    emit_words(out, "bb_shader_smaa_vertex_edges", compile_shader("vert", "EDGES"))
    emit_words(out, "bb_shader_smaa_vertex_weights", compile_shader("vert", "WEIGHTS"))
    emit_words(out, "bb_shader_smaa_vertex_blend", compile_shader("vert", "BLEND"))
    emit_words(out, "bb_shader_smaa_vertex_resolve", compile_shader("vert", "RESOLVE"))
    for p in PASSES:
        emit_words(out, "bb_shader_smaa_fragment_" + p.lower(), compile_shader("frag", p))
    out.write("// 160 x 560, two 8 bit channels.\n")
    emit_bytes(out, "bb_smaa_area_texture", area)
    out.write("// 64 x 16, one 8 bit channel.\n")
    emit_bytes(out, "bb_smaa_search_texture", search)
